diff --git a/cmd/entire/cli/agent/agent.go b/cmd/entire/cli/agent/agent.go
index 73f548e4..b1532f43 100644
--- a/cmd/entire/cli/agent/agent.go
+++ b/cmd/entire/cli/agent/agent.go
@@ -202,6 +202,29 @@ type SidecarImageProvider interface {
 	SidecarImages(ctx context.Context, sessionRef string) ([]CompactedTranscriptAsset, error)
 }

+// TranscriptSanitizer is implemented by agents whose native transcript format
+// carries state that Entire must not keep in its own copy — e.g. Codex rollouts
+// embed encrypted reasoning payloads and compaction blobs that are bound to the
+// originating session and cannot be replayed out of a checkpoint.
+//
+// Entire always leaves the agent's own transcript untouched; this transform applies
+// only to the copy Entire stores. Sanitizing before redaction is what keeps
+// non-replayable payloads out of storage AND keeps the redaction layers from
+// scanning megabytes of ciphertext they would only discard afterwards (base64 is
+// the pathological input for the entropy layer).
+//
+// Implementations must be pure byte transforms: idempotent (sanitizing an
+// already-sanitized transcript is a no-op), safe to call from hooks, and never
+// dependent on the agent process being alive.
+type TranscriptSanitizer interface {
+	Agent
+
+	// SanitizeTranscriptForStorage returns the transcript with non-portable state
+	// removed. It must return the input unchanged rather than nil when it cannot
+	// parse the transcript, so a sanitizer failure never loses the session.
+	SanitizeTranscriptForStorage(data []byte) []byte
+}
+
 // TokenCalculator provides token usage calculation for a session.
 // The framework calls this during step save and checkpoint if implemented.
 type TokenCalculator interface {
diff --git a/cmd/entire/cli/agent/capabilities.go b/cmd/entire/cli/agent/capabilities.go
index 9c4ed549..77bbe98d 100644
--- a/cmd/entire/cli/agent/capabilities.go
+++ b/cmd/entire/cli/agent/capabilities.go
@@ -17,9 +17,10 @@ type CapabilityDeclarer interface {
 // can deserialize directly into this type.
 //
 // Not every optional interface appears here: built-in-only capabilities that
-// have no external-protocol equivalent (SessionBaseDirProvider, ModelExtractor)
-// are intentionally excluded — their As* helpers resolve by type assertion
-// alone, with no DeclaredCaps gate.
+// have no external-protocol equivalent (SessionBaseDirProvider, ModelExtractor,
+// SkillEventExtractor, TranscriptSanitizer) are intentionally excluded — their
+// As* helpers resolve by type assertion alone (see builtinCapability), with no
+// DeclaredCaps gate.
 type DeclaredCaps struct {
 	Hooks                  bool `json:"hooks"`
 	TranscriptAnalyzer     bool `json:"transcript_analyzer"`
@@ -89,6 +90,35 @@ func AsSidecarImageProvider(ag Agent) (SidecarImageProvider, bool) {
 	return p, ok
 }

+// AsTranscriptSanitizer returns the agent as TranscriptSanitizer if it implements
+// the interface. This is a pure local byte transform with no external process to
+// negotiate with, so it needs no DeclaredCaps gate.
+func AsTranscriptSanitizer(ag Agent) (TranscriptSanitizer, bool) {
+	return builtinCapability[TranscriptSanitizer](ag)
+}
+
+// SanitizeTranscriptForStorage applies the agent's storage sanitizer when it has one
+// and returns data unchanged otherwise. Every path that stores a transcript copy
+// should call this BEFORE redaction — see TranscriptSanitizer for why. A no-op for
+// agents without the capability and idempotent for those with it, so it is safe to
+// call on any transcript from any path.
+func SanitizeTranscriptForStorage(ag Agent, data []byte) []byte {
+	if len(data) == 0 {
+		return data
+	}
+	s, ok := AsTranscriptSanitizer(ag)
+	if !ok {
+		return data
+	}
+	sanitized := s.SanitizeTranscriptForStorage(data)
+	if sanitized == nil {
+		// Defensive: the interface forbids this, but a nil return would silently
+		// drop the whole session. Prefer the unsanitized transcript over none.
+		return data
+	}
+	return sanitized
+}
+
 // AsTokenCalculator returns the agent as TokenCalculator if it both
 // implements the interface and (for CapabilityDeclarer agents) has declared the capability.
 func AsTokenCalculator(ag Agent) (TokenCalculator, bool) {
