	s := string(b)
	redacted, err := JSONLContentWithPrivacyFilter(ctx, s)
	if err != nil {
		return RedactedBytes{}, err
	}
	if redacted == s {
		return RedactedBytes{data: b}, nil
	}
	return RedactedBytes{data: []byte(redacted)}, nil
}

